<script setup lang="ts">
type Tenant={id:string;name:string;slug:string;plan:string;status:string;created_at:string};type Page={tenants:Tenant[];next_cursor?:string}
const {$platformApi}=useNuxtApp();const query=ref('');const status=ref('');const request=computed(()=>`/admin/backoffice/tenants?q=${encodeURIComponent(query.value)}&status=${encodeURIComponent(status.value)}`);const {data,refresh}=await useAsyncData('workspaces',()=> $platformApi<Page>(request.value),{server:false,watch:[request]});function submit(){void refresh()}
</script>
<template><section><p class="eyebrow">Workspace directory</p><h1 class="title">Every account,<br>in context.</h1><form class="panel" @submit.prevent="submit"><input v-model="query" placeholder="Search name or slug"><select v-model="status"><option value="">All statuses</option><option>active</option><option>trial</option><option>suspended</option><option>cancelled</option></select><button class="button">Filter</button></form><table class="table"><thead><tr><th>Workspace</th><th>Plan</th><th>Status</th><th>Created</th></tr></thead><tbody><tr v-for="tenant in data?.tenants" :key="tenant.id"><td><NuxtLink :to="`/workspaces/${tenant.id}`">{{ tenant.name }}<br><span class="muted">{{ tenant.slug }}</span></NuxtLink></td><td>{{ tenant.plan }}</td><td>{{ tenant.status }}</td><td>{{ new Date(tenant.created_at).toLocaleDateString() }}</td></tr></tbody></table></section></template>
